CREATE   PROCEDURE [synapse_ce].[usp_Insert_connectionrole]
AS
BEGIN
	INSERT INTO [synapse_ce].[connectionrole]
	(
		[category],
		[componentstate],
		[connectionroleid],
		[connectionroleidunique],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[description],
		[Id],
		[importsequencenumber],
		[introducedversion],
		[iscustomizable],
		[ismanaged],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[name],
		[organizationid],
		[organizationid_entitytype],
		[organizationidname],
		[overwritetime],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[solutionid],
		[statecode],
		[statuscode],
		[supportingsolutionid],
		[versionnumber]
	)
	SELECT 
		stg.[category],
		stg.[componentstate],
		stg.[connectionroleid],
		stg.[connectionroleidunique],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[description],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[introducedversion],
		stg.[iscustomizable],
		stg.[ismanaged],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[name],
		stg.[organizationid],
		stg.[organizationid_entitytype],
		stg.[organizationidname],
		stg.[overwritetime],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[solutionid],
		stg.[statecode],
		stg.[statuscode],
		stg.[supportingsolutionid],
		stg.[versionnumber]	
	FROM [staging_ce].[connectionrole] stg
		LEFT JOIN [synapse_ce].[connectionrole] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
